                    ? "bg-slate-900 text-white"
                    : "border border-slate-200 bg-white text-slate-700 hover:bg-slate-50"
                }`}
              >
                {label}
              </button>
            ))}
          </div>
          <ChartCard
            title="Pace mismatch ??? campuses vs wires, fuel, and price"
            subtitle="LBNL timelines + Mid-Year price geography added to the race clock"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, right: 16, top: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="campusYears"
                    name="Campus years"
                    unit="y"
                    tick={{ fontSize: 11 }}
                    domain={[1, 7]}
                    label={{
                      value: "Campus / project years",
                      position: "insideBottom",
                      offset: -2,
                      style: { fontSize: 11 },
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="interconnectYears"
                    name="Interconnect years"
                    unit="y"
                    tick={{ fontSize: 11 }}
                    domain={[0.5, 7]}
                    label={{
                      value: "Wires / constraint years",
                      angle: -90,
                      position: "insideLeft",
                      style: { fontSize: 11 },
                    }}
                  />
                  <ZAxis range={[80, 200]} />
                  <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                  <ReferenceLine
                    segment={[
                      { x: 1, y: 1 },
                      { x: 7, y: 7 },
                    ]}
                    stroke="#cbd5e1"
                    strokeDasharray="4 4"
                  />
                  {(["campus", "wires", "fuel", "price", "unlock"] as const).map(
                    (cluster) => {
                      const pts = pacePoints.filter((p) => p.cluster === cluster);
                      if (!pts.length) return null;
                      return (
                        <Scatter
                          key={cluster}
                          name={cluster}
                          data={pts}
                          fill={CLUSTER_COLORS[cluster]}
                        />
                      );
                    },
                  )}
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}
    </div>
  );
}

